function DataTable({
  density = DEFAULT_AXES["density"],
  className = "",
  axisValues = {},
  previewStyle
} = {}) {
  const activeAxes = { ...DEFAULT_AXES, ...axisValues, "density": density };
  const selected = FIGMA_LAYOUT.find((item) => Object.entries(item.axes || {}).every(([axis, value]) => activeAxes[axis] === value)) || FIGMA_LAYOUT[0];
  return <DataTableFigmaLayer figmaIndex={selected.index} previewStyle={previewStyle} className={className} />;
}

const Demo = () => (
  <div className="thiga-figma-set--datatable">
    <style>{css}</style>
    {FIGMA_LAYOUT.map((item) => (
      <DataTable
        key={item.index}
        axisValues={item.axes}
        density={item.axes["density"]}
        previewStyle={{ left: item.x, top: item.y }}
      />
    ))}
  </div>
);

render(<Demo />);
