function ListItem({
  density = DEFAULT_AXES["density"],
  state = DEFAULT_AXES["state"],
  className = "",
  axisValues = {},
  previewStyle
} = {}) {
  const activeAxes = { ...DEFAULT_AXES, ...axisValues, "density": density, "state": state };
  const selected = FIGMA_LAYOUT.find((item) => Object.entries(item.axes || {}).every(([axis, value]) => activeAxes[axis] === value)) || FIGMA_LAYOUT[0];
  return <ListItemFigmaLayer figmaIndex={selected.index} previewStyle={previewStyle} className={className} />;
}

const Demo = () => (
  <div className="thiga-figma-set--listitem">
    <style>{css}</style>
    {FIGMA_LAYOUT.map((item) => (
      <ListItem
        key={item.index}
        axisValues={item.axes}
        density={item.axes["density"]}
        state={item.axes["state"]}
        previewStyle={{ left: item.x, top: item.y }}
      />
    ))}
  </div>
);

render(<Demo />);
